  animation-delay: calc(var(--bea-i) * 80ms);
}

.bea-espace--actif {
  transition:
    translate 0.28s ease,
    box-shadow 0.28s ease,
    border-color 0.28s ease;
}

.bea-espace--actif::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(
    115deg,
    transparent 0%,
    rgb(255 255 255 / 0) 42%,
    rgb(255 255 255 / 0.45) 50%,
    rgb(255 255 255 / 0) 58%,
    transparent 100%
  );
  transform: translateX(-130%);
}

.bea-espace--actif:focus-visible {
  outline: 2px solid #1a5278;
  outline-offset: 2px;
}

.bea-espace--actif:hover {
  translate: 0 -5px;
  border-color: #b9d6ec;
  box-shadow: 0 16px 36px rgb(26 82 120 / 0.14);
}

.bea-espace--actif:hover::after {
  transition: transform 0.7s ease;
  transform: translateX(130%);
}

.bea-espace--actif:hover .bea-espace__icon {
  transform: scale(1.06);
  background: #d7eaf7;
}

.bea-espace--actif:hover .bea-espace__scene {
