  background: rgb(255 255 255 / 0.1);
  color: rgb(226 232 240 / 0.78);
  white-space: nowrap;
}

.bea-admin__footer {
  padding: 0.75rem 1rem;
  border-top: 1px solid rgb(255 255 255 / 0.08);
  font-size: 0.6875rem;
  color: rgb(148 163 184 / 0.7);
  line-height: 1.4;
  overflow: hidden;
  white-space: nowrap;
  transition: opacity 0.15s ease, padding 0.22s ease, max-height 0.22s ease;
}

/* --- Mode compact (icônes seules) --- */
.bea-admin--collapsed .bea-admin__brand {
  padding: 0.55rem 0.35rem 0.75rem;
  gap: 0;
}

.bea-admin--collapsed .bea-admin__logo {
  width: 2rem;
}

.bea-admin--collapsed .bea-admin__brand-text,
.bea-admin--collapsed .bea-admin__group-label,
.bea-admin--collapsed .bea-admin__link-label,
.bea-admin--collapsed .bea-admin__soon .bea-badge,
.bea-admin--collapsed .bea-admin__footer {
  opacity: 0;
  max-height: 0;
  padding-top: 0;
  padding-bottom: 0;
  margin: 0;
  pointer-events: none;
  visibility: hidden;
}

.bea-admin--collapsed .bea-admin__nav {
  padding: 0.5rem 0.35rem;
}

.bea-admin--collapsed .bea-admin__group {
  margin-bottom: 0.15rem;
}

.bea-admin--collapsed .bea-admin__link,
.bea-admin--collapsed .bea-admin__soon {
  justify-content: center;
  gap: 0;
  padding: 0.55rem 0.35rem;
}

.bea-admin--collapsed .bea-admin__link--on {
  box-shadow: inset 3px 0 0 var(--bea-admin-nav-active);
}

.bea-admin--collapsed .bea-admin__soon {
  pointer-events: auto;
}

.bea-admin--collapsed .bea-admin__footer {
  border-top-width: 0;
}

.bea-admin__tooltip {
  position: fixed;
  z-index: 80;
  transform: translateY(-50%);
  padding: 0.35rem 0.6rem;
  border-radius: 0.4rem;
  background: #0f172a;
  color: #f8fafc;
  font-size: 0.75rem;
  font-weight: 600;
  line-height: 1.2;
  white-space: nowrap;
  pointer-events: none;
  box-shadow: 0 6px 18px rgb(15 23 42 / 0.28);
}

@media (max-width: 900px) {
  .bea-admin {
    --bea-admin-side-width: 15.5rem;
  }

  .bea-admin--collapsed {
    --bea-admin-side-width: 4rem;
  }
}

@media (max-width: 720px) {
  .bea-admin {
    --bea-admin-side-width: 14rem;
  }

  .bea-admin--collapsed {
    --bea-admin-side-width: 3.75rem;
  }

  .bea-admin__top-title {
    font-size: 1rem;
  }

  .bea-admin__user {
    display: none;
  }

  .bea-admin__main {
    padding: 1rem;
  }
}

.bea-admin__content {
  min-width: 0;
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.bea-admin__top {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  min-height: 4rem;
  padding: 0.75rem 1.5rem;
  background: #fff;
  border-bottom: 1px solid var(--bea-line);
}

.bea-admin__top-title {
  font-size: 1.125rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  color: #0f172a;
}

.bea-admin__top-actions {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  flex-shrink: 0;
}

.bea-admin__userchip {
  display: flex;
  align-items: center;
  gap: 0.55rem;
}

.bea-admin__avatar {
  width: 2.15rem;
  height: 2.15rem;
  border-radius: 999px;
  display: grid;
  place-items: center;
  background: var(--bea-brand-600);
  color: #fff;
  font-weight: 700;
  font-size: 0.85rem;
}

.bea-admin__user {
  font-size: 0.875rem;
  font-weight: 600;
  color: #0f172a;
}

.bea-admin__home,
.bea-admin__logout {
  appearance: none;
  border: 1px solid #3498db;
  background: #fff;
  color: #21618c;
  font: inherit;
  font-size: 0.82rem;
  font-weight: 600;
  padding: 0.4rem 0.8rem;
  border-radius: 0.45rem;
  text-decoration: none;
  cursor: pointer;
}

.bea-admin__home:hover,
.bea-admin__logout:hover {
  background: #dbeafe;
  border-color: #2874a6;
  color: #1a5278;
}

.bea-admin__main {
  flex: 1;
  min-width: 0;
  padding: 1.5rem;
  overflow: auto;
}

.bea-admin-dash__head h1 {
  margin: 0 0 0.25rem;
  font-size: 1.45rem;
}

.bea-admin-dash__head--hero {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  margin-bottom: 1.1rem;
  padding: 1.1rem 1.2rem;
  border: 1px solid var(--bea-line);
  border-radius: 0.9rem;
  background:
    radial-gradient(120% 140% at 100% 0%, rgb(40 116 166 / 0.14), transparent 55%),
    linear-gradient(135deg, #f8fbfe 0%, #eef5fb 100%);
}

.bea-admin-dash__head--hero h1 {
  margin: 0.1rem 0 0.35rem;
  font-size: 1.65rem;
  letter-spacing: -0.02em;
  color: var(--bea-brand-900);
}

.bea-admin-dash__head--hero > div > p:last-child {
  margin: 0;
  max-width: 36rem;
  color: var(--bea-ink-muted);
  font-size: 0.92rem;
  line-height: 1.45;
}

.bea-admin-dash__eyebrow {
  margin: 0;
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bea-brand-700);
}

.bea-admin-dash__head p,
.bea-admin-dash__loading,
.bea-admin-panel__empty {
  margin: 0 0 1rem;
  color: var(--bea-ink-muted);
  font-size: 0.9rem;
}

.bea-admin-panel__hint {
  margin: 0 0 0.85rem;
  font-size: 0.875rem;
  line-height: 1.45;
  color: var(--bea-ink-muted);
}

.bea-admin-dash__error {
  margin: 0 0 1rem;
  color: #b91c1c;
  font-weight: 600;
}

.bea-admin-dash__ok {
  margin: 0 0 1rem;
  color: #166534;
  font-weight: 600;
}

.bea-admin-kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(11.5rem, 1fr));
  gap: 0.85rem;
  margin-bottom: 1.25rem;
}

.bea-admin-kpi {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  background: #fff;
  border: 1px solid var(--bea-line);
  border-radius: 0.75rem;
  padding: 0.95rem 1rem;
  animation: bea-admin-rise 0.4s ease both;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
}

.bea-admin-kpi:hover {
  transform: translateY(-3px);
  border-color: var(--bea-brand-400);
  box-shadow: 0 12px 28px rgb(26 82 120 / 0.12);
}

.bea-admin-kpi__icon {
  display: grid;
  place-items: center;
  width: 2.4rem;
  height: 2.4rem;
  flex-shrink: 0;
  border-radius: 0.7rem;
  background: rgb(40 116 166 / 0.12);
  color: var(--bea-brand-700);
}

.bea-admin-kpi__icon bea-admin-icon {
  font-size: 1.25rem;
  width: 1.25rem;
  height: 1.25rem;
  line-height: 1;
}

.bea-admin-kpi[data-tone='org'] .bea-admin-kpi__icon {
  background: rgb(13 148 136 / 0.12);
  color: #0f766e;
}

.bea-admin-kpi[data-tone='modules'] .bea-admin-kpi__icon {
  background: rgb(79 70 229 / 0.12);
  color: #4338ca;
}

.bea-admin-kpi[data-tone='sessions'] .bea-admin-kpi__icon {
  background: rgb(2 132 199 / 0.12);
  color: #0369a1;
}

.bea-admin-kpi[data-tone='alert'] .bea-admin-kpi__icon {
  background: rgb(217 119 6 / 0.14);
  color: #b45309;
}

.bea-admin-kpi[data-tone='actions'] .bea-admin-kpi__icon {
  background: rgb(22 163 74 / 0.12);
  color: #15803d;
}

@keyframes bea-admin-rise {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

.bea-admin-kpi__label {
  margin: 0;
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--bea-ink-muted);
}

.bea-admin-kpi__value {
  margin: 0.2rem 0 0;
  font-size: 1.55rem;
  font-weight: 800;
  color: var(--bea-brand-900);
}

.bea-admin-kpi__hint {
  margin: 0.15rem 0 0;
  font-size: 0.8rem;
  color: var(--bea-ink-muted);
}

.bea-admin-panels {
  display: grid;
  grid-template-columns: minmax(0, 1.6fr) minmax(14rem, 0.8fr);
  gap: 1rem;
}

.bea-admin-charts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1rem;
  margin-bottom: 1.15rem;
}

.bea-admin-chart {
  min-height: 14.5rem;
}

.bea-admin-chart__foot {
  margin: 0.85rem 0 0;
  font-size: 0.82rem;
  color: var(--bea-ink-muted);
}

.bea-admin-bars {
  display: flex;
  align-items: flex-end;
  gap: 0.55rem;
  min-height: 10rem;
  padding: 0.25rem 0.15rem 0;
}

.bea-admin-bars__col {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.35rem;
  min-width: 0;
}

.bea-admin-bars__value {
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--bea-brand-800);
}

.bea-admin-bars__track {
  width: 100%;
  max-width: 2.4rem;
  height: 7.5rem;
  display: flex;
  align-items: flex-end;
  border-radius: 0.55rem 0.55rem 0.35rem 0.35rem;
  background: rgb(40 116 166 / 0.08);
  overflow: hidden;
}

.bea-admin-bars__fill {
  width: 100%;
  border-radius: 0.45rem 0.45rem 0.2rem 0.2rem;
  background: linear-gradient(180deg, #5dade2 0%, #1a5278 100%);
  transition: height 0.45s ease;
}

.bea-admin-bars__label {
  font-size: 0.72rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: var(--bea-ink-muted);
}

.bea-admin-donut {
  display: grid;
  grid-template-columns: 7.5rem minmax(0, 1fr);
  grid-template-rows: auto auto;
  gap: 0.35rem 1rem;
  align-items: center;
  position: relative;
}

.bea-admin-donut__svg {
  width: 7.5rem;
  height: 7.5rem;
  grid-row: 1 / span 2;
  transform: rotate(-90deg);
}

.bea-admin-donut__ring {
  transition: stroke-dasharray 0.4s ease;
}

.bea-admin-donut__center {
  position: absolute;
  left: 0;
  top: 50%;
  width: 7.5rem;
  transform: translateY(-50%);
  display: grid;
  place-items: center;
  pointer-events: none;
}

.bea-admin-donut__center strong {
  font-size: 1.15rem;
  line-height: 1;
  color: var(--bea-brand-900);
}

.bea-admin-donut__center span {
  font-size: 0.68rem;
  color: var(--bea-ink-muted);
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.bea-admin-donut__legend {
  grid-column: 2;
  grid-row: 1 / span 2;
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 0.45rem;
}

.bea-admin-donut__legend li {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  font-size: 0.84rem;
}

.bea-admin-donut__legend strong {
  margin-left: auto;
  font-size: 0.78rem;
  color: var(--bea-brand-900);
}

.bea-admin-donut__swatch {
  width: 0.65rem;
  height: 0.65rem;
  border-radius: 0.2rem;
  flex-shrink: 0;
}

.bea-admin-hbar {
  list-style: none;
  margin: 0.25rem 0 0;
  padding: 0;
  display: grid;
  gap: 0.85rem;
}

.bea-admin-hbar__meta {
  display: flex;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.3rem;
  font-size: 0.84rem;
}

.bea-admin-hbar__meta strong {
  color: var(--bea-brand-900);
}

.bea-admin-hbar__track {
  height: 0.55rem;
  border-radius: 999px;
  background: rgb(40 116 166 / 0.1);
  overflow: hidden;
}

.bea-admin-hbar__fill {
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #2874a6, #1a5278);
  transition: width 0.45s ease;
}

.bea-admin-hbar__fill[data-key='bientot'] {
  background: linear-gradient(90deg, #5dade2, #2874a6);
}

.bea-admin-hbar__fill[data-key='inactif'] {
  background: linear-gradient(90deg, #94a3b8, #64748b);
}

.bea-admin-shortcuts {
  margin-bottom: 1.15rem;
}

.bea-admin-shortcuts > h2 {
  margin: 0 0 0.65rem;
  font-size: 1rem;
}

.bea-admin-shortcuts__grid {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 0.75rem;
}

.bea-admin-shortcut {
  display: flex;
  align-items: center;
  gap: 0.7rem;
  padding: 0.8rem 0.85rem;
  border: 1px solid var(--bea-line);
  border-radius: 0.75rem;
  background: #fff;
  color: inherit;
  text-decoration: none;
  transition: transform 0.18s ease, box-shadow 0.18s ease, border-color 0.18s ease;
  animation: bea-admin-rise 0.45s ease both;
}

.bea-admin-shortcut:hover {
  transform: translateY(-2px);
  border-color: var(--bea-brand-400);
  box-shadow: 0 10px 24px rgb(26 82 120 / 0.1);
}

.bea-admin-shortcut__icon {
  display: grid;
  place-items: center;
  width: 2.15rem;
  height: 2.15rem;
  flex-shrink: 0;
  border-radius: 0.65rem;
  background: rgb(40 116 166 / 0.12);
  color: var(--bea-brand-700);
}

.bea-admin-shortcut__icon bea-admin-icon {
  font-size: 1.15rem;
  width: 1.15rem;
  height: 1.15rem;
  line-height: 1;
}

.bea-admin-shortcut__copy {
  display: grid;
  gap: 0.1rem;
  min-width: 0;
}

.bea-admin-shortcut__copy strong {
  font-size: 0.88rem;
  color: var(--bea-brand-900);
}

.bea-admin-shortcut__copy span {
  font-size: 0.75rem;
  color: var(--bea-ink-muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.bea-admin-shortcut__chevron {
  margin-left: auto;
  color: var(--bea-ink-muted);
  font-size: 1.1rem !important;
}

.bea-admin-health__note {
  margin: 0.75rem 0 0;
  font-size: 0.78rem;
  color: var(--bea-ink-muted);
  line-height: 1.4;
}

.bea-admin-panels--equal {
  grid-template-columns: repeat(2, minmax(0, 1fr));
}

.bea-admin-panel {
  background: #fff;
  border: 1px solid var(--bea-line);
  border-radius: 0.75rem;
  padding: 1rem 1.1rem;
  animation: bea-admin-rise 0.45s ease both;
}

.bea-admin-panel--list {
  display: flex;
  flex-direction: column;
  min-height: 0;
}

.bea-admin-panel__scroll {
  overflow: auto;
  max-height: min(22rem, calc(100vh - 26rem));
}

.bea-admin-panel h2 {
  margin: 0 0 0.75rem;
  font-size: 1rem;
  flex: 0 0 auto;
}

.bea-admin-table__clip {
  max-width: 14rem;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.bea-admin-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.84rem;
}

.bea-admin-table th,
.bea-admin-table td {
  text-align: left;
  padding: 0.4rem 0.35rem;
  border-bottom: 1px solid var(--bea-line);
  vertical-align: top;
}

.bea-admin-table th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #fff;
  color: var(--bea-ink-muted);
  font-weight: 700;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}

.bea-admin-table tbody tr {
  transition: background 0.15s ease;
}

.bea-admin-table tbody tr:hover {
  background: #f8fafc;
}

.bea-admin-health {
  list-style: none;
  margin: 0;
  padding: 0;
}

.bea-admin-health li {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.4rem 0;
  border-bottom: 1px solid var(--bea-line);
  font-size: 0.9rem;
}

.bea-admin-health li strong {
  margin-left: auto;
  font-size: 0.78rem;
}

.bea-admin-health__dot {
  width: 0.65rem;
  height: 0.65rem;
  border-radius: 50%;
  background: #94a3b8;
}

.bea-admin-health__dot--ok {
  background: #16a34a;
  box-shadow: 0 0 0 0 rgb(22 163 74 / 0.45);
  animation: bea-admin-pulse 2.2s ease-out infinite;
}

@keyframes bea-admin-pulse {
  70% {
    box-shadow: 0 0 0 0.45rem rgb(22 163 74 / 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgb(22 163 74 / 0);
  }
}

.bea-admin-health__dot--ko {
  background: #dc2626;
  box-shadow: 0 0 0 0 rgb(220 38 38 / 0.4);
  animation: bea-admin-pulse-ko 1.8s ease-out infinite;
}

@keyframes bea-admin-pulse-ko {
  70% {
    box-shadow: 0 0 0 0.45rem rgb(220 38 38 / 0);
  }
  100% {
    box-shadow: 0 0 0 0 rgb(220 38 38 / 0);
