.bea-admin-supervis__banner {
  position: relative;
  overflow: hidden;
  display: flex;
  align-items: center;
  gap: 1rem;
  margin: 0 0 1.15rem;
  padding: 1.15rem 1.25rem;
  border-radius: 0.95rem;
  border: 1px solid var(--bea-line);
  background: #fff;
  animation: bea-admin-rise 0.45s ease both;
}

.bea-admin-supervis__banner--ok {
  border-color: #bfdbfe;
  background: linear-gradient(135deg, #eff6ff 0%, #fff 55%);
}

.bea-admin-supervis__banner--warn {
  border-color: #fde68a;
  background: linear-gradient(135deg, #fffbeb 0%, #fff 55%);
}

.bea-admin-supervis__banner-glow {
  position: absolute;
  inset: auto -20% -60% auto;
  width: 14rem;
  height: 14rem;
  border-radius: 50%;
  pointer-events: none;
  opacity: 0.35;
  background: radial-gradient(circle, #93c5fd 0%, transparent 70%);
  animation: bea-admin-supervis-glow 4.5s ease-in-out infinite;
}

.bea-admin-supervis__banner--warn .bea-admin-supervis__banner-glow {
  background: radial-gradient(circle, #fde68a 0%, transparent 70%);
}

@keyframes bea-admin-supervis-glow {
  0%,
  100% {
    transform: translate(0, 0) scale(1);
    opacity: 0.28;
  }
  50% {
    transform: translate(-8%, -6%) scale(1.08);
    opacity: 0.45;
  }
}

.bea-admin-supervis__banner-icon {
  position: relative;
  z-index: 1;
  display: grid;
  place-items: center;
  width: 3rem;
  height: 3rem;
  border-radius: 0.85rem;
  color: var(--bea-brand-700);
  background: rgb(40 116 166 / 0.14);
}

.bea-admin-supervis__banner--warn .bea-admin-supervis__banner-icon {
  color: #b45309;
  background: rgb(245 158 11 / 0.16);
}

.bea-admin-supervis__banner-icon bea-admin-icon {
  font-size: 1.55rem;
  width: 1.55rem;
  height: 1.55rem;
  line-height: 1;
}

.bea-admin-supervis__banner-copy {
  position: relative;
  z-index: 1;
  min-width: 0;
}

.bea-admin-supervis__banner-kicker {
  margin: 0 0 0.15rem;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bea-ink-muted);
}

.bea-admin-supervis__banner-copy h2 {
  margin: 0 0 0.2rem;
  font-size: 1.2rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #0f172a;
}

.bea-admin-supervis__banner-copy p {
  margin: 0;
  font-size: 0.875rem;
  color: var(--bea-ink-muted);
}

.bea-admin-supervis__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(11.5rem, 1fr));
  gap: 0.75rem;
  margin-bottom: 1.15rem;
}

.bea-admin-supervis__tile {
  --delay: 0ms;
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 0.65rem;
  padding: 0.9rem 0.95rem;
