.bea-admin-mstates__summary {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin: 0 0 1rem;
}

.bea-admin-mstates__chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.4rem 0.7rem;
  border-radius: 999px;
  border: 1px solid #bfdbfe;
  background: #eff6ff;
  animation: bea-admin-rise 0.35s ease both;
}

.bea-admin-mstates__chip strong {
  font-size: 0.9rem;
  color: var(--bea-brand-900);
}

.bea-admin-mstates__chip span {
  font-size: 0.75rem;
  font-weight: 600;
  color: #475569;
}

.bea-admin-mstates__chip[data-statut='actif'] {
  border-color: #bbf7d0;
  background: #f0fdf4;
}

.bea-admin-mstates__chip[data-statut='actif'] strong {
  color: #166534;
}

.bea-admin-mstates__chip[data-statut='mise_a_jour'],
.bea-admin-mstates__chip[data-statut='maintenance'],
.bea-admin-mstates__chip[data-statut='suspendu'],
.bea-admin-mstates__chip[data-statut='bloque'] {
  border-color: #fde68a;
  background: #fffbeb;
}

.bea-admin-mstates__chip[data-statut='mise_a_jour'] strong,
.bea-admin-mstates__chip[data-statut='maintenance'] strong,
.bea-admin-mstates__chip[data-statut='suspendu'] strong,
.bea-admin-mstates__chip[data-statut='bloque'] strong {
  color: #9a3412;
}

.bea-admin-mstates__list {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.bea-admin-mstates__card {
  --delay: 0ms;
  margin: 0;
  animation: bea-admin-rise 0.45s ease both;
  animation-delay: var(--delay);
}

.bea-admin-mstates__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.85rem;
  margin-bottom: 1rem;
  padding-bottom: 0.85rem;
  border-bottom: 1px solid var(--bea-line);
}

.bea-admin-mstates__head h2 {
  margin: 0 0 0.25rem;
}

.bea-admin-mstates__meta {
  margin: 0;
  font-size: 0.82rem;
  color: var(--bea-ink-muted);
}

.bea-admin-mstates__meta code {
  font-size: 0.78rem;
  padding: 0.1rem 0.35rem;
  border-radius: 0.3rem;
  background: #f1f5f9;
  color: #334155;
}

.bea-admin-mstates__pill {
  flex-shrink: 0;
  display: inline-flex;
  padding: 0.28rem 0.65rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: var(--bea-brand-900);
  background: #dbeafe;
}

.bea-admin-mstates__pill[data-statut='actif'] {
  color: #166534;
  background: #dcfce7;
}

.bea-admin-mstates__pill[data-statut='mise_a_jour'],
.bea-admin-mstates__pill[data-statut='maintenance'],
.bea-admin-mstates__pill[data-statut='suspendu'],
.bea-admin-mstates__pill[data-statut='bloque'] {
  color: #9a3412;
  background: #ffedd5;
}

.bea-admin-mstates__pill[data-statut='bientot'],
.bea-admin-mstates__pill[data-statut='developpement'] {
  color: #1e3a8a;
  background: #dbeafe;
}

.bea-admin-mstates__pill[data-statut='inactif'],
.bea-admin-mstates__pill[data-statut='archive'] {
  color: #475569;
  background: #f1f5f9;
}

.bea-admin-mstates__message textarea {
  min-height: 4.5rem;
}

/* Versions */
.bea-admin-versions__card {
  margin-bottom: 1rem;
}

.bea-admin-versions__history-head {
  margin-bottom: 0.35rem;
}

.bea-admin-versions__history-head h2 {
  margin-bottom: 0.55rem;
}

.bea-admin-versions__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.55rem;
}

.bea-admin-versions__list li {
  --delay: 0ms;
  padding: 0.85rem 0.95rem;
  border-radius: 0.7rem;
  border: 1px solid var(--bea-line);
  background: linear-gradient(180deg, #f8fbff 0%, #fff 70%);
  animation: bea-admin-rise 0.4s ease both;
  animation-delay: var(--delay);
}

.bea-admin-versions__ver {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.75rem;
  margin-bottom: 0.25rem;
}

.bea-admin-versions__ver strong {
  font-size: 1rem;
  color: var(--bea-brand-900);
}

.bea-admin-versions__ver span {
  font-size: 0.78rem;
  color: var(--bea-ink-muted);
}

.bea-admin-versions__list p {
  margin: 0;
  font-size: 0.88rem;
  color: #334155;
  line-height: 1.45;
}

@media (prefers-reduced-motion: reduce) {
  .bea-admin-maint__health li,
  .bea-admin-mstates__card,
  .bea-admin-mstates__chip,
  .bea-admin-versions__list li,
  .bea-admin-maint__submit,
  .bea-admin-mstates__submit,
  .bea-admin-versions__submit {
    animation: none !important;
    transition: none !important;
  }

