  }
}

/* Centre de notifications */
.bea-admin-ncenter__kicker {
  margin: 0 0 0.15rem;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--bea-ink-muted);
}

.bea-admin-ncenter__filters {
  margin-bottom: 1rem;
}

.bea-admin-ncenter__panel h2 {
  margin: 0;
}

.bea-admin-ncenter__table td {
  vertical-align: top;
}

.bea-admin-ncenter__emetteur {
  font-weight: 600;
  color: #0f172a;
}

.bea-admin-ncenter__cat {
  display: inline-flex;
  padding: 0.18rem 0.5rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--bea-brand-900);
  background: #dbeafe;
}

.bea-admin-ncenter__prio {
  display: inline-flex;
  padding: 0.18rem 0.5rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.02em;
  text-transform: uppercase;
  color: #1e3a8a;
  background: #dbeafe;
}

.bea-admin-ncenter__prio[data-prio='attention'] {
  color: #9a3412;
  background: #ffedd5;
}

.bea-admin-ncenter__prio[data-prio='avertissement'] {
  color: #92400e;
  background: #fef3c7;
}

.bea-admin-ncenter__prio[data-prio='critique'] {
  color: #991b1b;
  background: #fee2e2;
}

.bea-admin-ncenter__mono {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.75rem;
  color: #64748b;
  white-space: nowrap;
}

.bea-admin-ncenter__table tbody tr[data-priorite='critique'] {
  background: #fff7f7;
}

.bea-admin-ncenter__table tbody tr[data-priorite='avertissement'] {
  background: #fffbeb;
}

.bea-admin-dl {
  display: grid;
  gap: 0.65rem 1rem;
  margin: 0;
}

.bea-admin-dl > div {
  display: grid;
  grid-template-columns: minmax(8rem, 12rem) minmax(0, 1fr);
  gap: 0.5rem 1rem;
  align-items: baseline;
  padding-bottom: 0.55rem;
  border-bottom: 1px solid var(--bea-line);
}

.bea-admin-dl dt {
  margin: 0;
  color: var(--bea-ink-muted);
  font-size: 0.78rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

.bea-admin-dl dd {
  margin: 0;
  font-size: 0.9rem;
  word-break: break-word;
}

@media (max-width: 1100px) {
  .bea-admin-charts {
    grid-template-columns: 1fr;
  }

  .bea-admin-shortcuts__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}

@media (max-width: 840px) {
  .bea-admin-panels,
  .bea-admin-panels--equal,
  .bea-admin-charts,
  .bea-admin-shortcuts__grid {
    grid-template-columns: 1fr;
  }

  .bea-admin-dash__head--hero {
    flex-direction: column;
  }

  .bea-admin {
    height: auto;
    min-height: 100vh;
  }

  .bea-admin__side {
    max-height: 22rem;
  }

  .bea-admin__user {
    display: none;
  }
}
