  justify-self: start;
  margin-top: 0.15rem;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  padding: 0.18rem 0.45rem;
  border-radius: 999px;
  background: #e2e8f0;
  color: #475569;
}

.bea-admin-sec__policy-tag[data-source='db'] {
  background: #dbeafe;
  color: #1a5278;
}

.bea-admin-sec__policy-btn {
  justify-self: start;
  margin-top: 0.35rem;
  padding: 0.35rem 0.7rem;
  font-size: 0.8rem;
}

