  padding: 0.2rem 0.5rem;
  border-radius: 0.4rem;
  background: #f1f5f9;
  color: #475569;
  font-size: 0.78rem;
  font-weight: 600;
}

.bea-sec-inc__pill {
  display: inline-flex;
  align-items: center;
  padding: 0.2rem 0.55rem;
  border-radius: 999px;
  font-size: 0.74rem;
  font-weight: 700;
  text-transform: lowercase;
  background: #e2e8f0;
  color: #334155;
}

.bea-sec-inc__pill[data-niveau='faible'] {
  background: #e0f2fe;
  color: #0369a1;
}

.bea-sec-inc__pill[data-niveau='moyen'] {
  background: #fef3c7;
  color: #92400e;
}

.bea-sec-inc__pill[data-niveau='eleve'],
.bea-sec-inc__pill[data-niveau='Ã©levÃ©'] {
  background: #ffedd5;
  color: #c2410c;
}

.bea-sec-inc__pill[data-niveau='critique'] {
  background: #fee2e2;
  color: #b91c1c;
}

.bea-sec-inc__pill[data-statut='ouvert'] {
  background: #dbeafe;
  color: #1d4ed8;
}

.bea-sec-inc__pill[data-statut='en_analyse'],
.bea-sec-inc__pill[data-statut='en_traitement'] {
  background: #fef3c7;
  color: #a16207;
}

.bea-sec-inc__pill[data-statut='resolu'],
.bea-sec-inc__pill[data-statut='clos'] {
  background: #dcfce7;
  color: #166534;
}

.bea-sec-inc__table .bea-admin-table__actions {
  white-space: nowrap;
}

@media (max-width: 720px) {
  .bea-sec-hub__grid--top,
  .bea-sec-hub__grid--bottom {
    grid-template-columns: 1fr;
  }

  .bea-sec-auth__grid {
    grid-template-columns: 1fr;
  }

  .bea-sec-auth__intro,
  .bea-sec-inc__intro,
  .bea-sec-inc__list-head {
    flex-direction: column;
  }

  .bea-sec-overlay {
    border-radius: 0.7rem;
  }
}

/* --- Stock & Fournitures (Moyens Généraux) --- */
.bea-stock {
  --bea-stock-navy: #0f172a;
  --bea-stock-brand: #1a5278;
  display: grid;
  grid-template-columns: 15.5rem minmax(0, 1fr);
  min-height: 100vh;
  background: #f4f7fb;
  color: #0f172a;
}

.bea-stock__side {
  display: flex;
  flex-direction: column;
  background: linear-gradient(180deg, #1a5278 0%, #0f172a 70%);
  color: #e2e8f0;
}

.bea-stock__brand {
  display: flex;
  gap: 0.75rem;
  align-items: center;
  padding: 1rem;
  color: inherit;
  text-decoration: none;
  border-bottom: 1px solid rgb(255 255 255 / 0.1);
}

.bea-stock__brand strong {
  display: block;
  font-size: 0.9rem;
}

.bea-stock__brand span {
  display: block;
  font-size: 0.7rem;
  opacity: 0.75;
}

.bea-stock__nav {
  display: flex;
  flex-direction: column;
  gap: 0.2rem;
  padding: 0.75rem 0.5rem;
  flex: 1;
}

.bea-stock__link {
  display: flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.55rem 0.7rem;
  border-radius: 0.45rem;
  color: rgb(226 232 240 / 0.9);
  text-decoration: none;
  font-size: 0.875rem;
  font-weight: 500;
}

.bea-stock__link .material-icons {
  font-size: 1.2rem;
}

.bea-stock__link:hover,
.bea-stock__link--on {
  background: rgb(255 255 255 / 0.1);
  color: #fff;
}

.bea-stock__footer {
  padding: 0.75rem;
  border-top: 1px solid rgb(255 255 255 / 0.1);
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  font-size: 0.8rem;
}

.bea-stock__footer a,
.bea-stock__footer button {
  color: #cbd5e1;
  background: none;
  border: 0;
  text-align: left;
  cursor: pointer;
  font: inherit;
  text-decoration: none;
}

.bea-stock__main {
  min-width: 0;
  padding: 1.25rem 1.5rem 2rem;
  overflow: auto;
}

/* Contenu métier MG dans le shell commun (pas de sidebar dédiée). */
.bea-stock-page {
  max-width: 72rem;
}

.bea-stock-page__head h1 {
  margin: 0.15rem 0 0.35rem;
  font-size: 1.45rem;
}

.bea-stock-page__kicker {
  margin: 0;
  font-size: 0.75rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #64748b;
}

.bea-stock-page__error {
  color: #b91c1c;
}

.bea-stock-page__ok {
  color: #166534;
}

.bea-stock-kpis {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));
  gap: 0.75rem;
  margin-bottom: 1.25rem;
}

.bea-stock-kpis article {
  background: #fff;
  border: 1px solid #dbe3ee;
  border-radius: 0.75rem;
  padding: 0.85rem 1rem;
}

.bea-stock-kpis span {
  display: block;
  font-size: 0.75rem;
  color: #64748b;
}

.bea-stock-kpis strong {
  font-size: 1.4rem;
}

.bea-stock-kpis article[data-tone='warn'] strong {
  color: #b45309;
}

.bea-stock-kpis article[data-tone='danger'] strong {
  color: #b91c1c;
}

.bea-stock-charts {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}

.bea-stock-panel {
  background: #fff;
  border: 1px solid #dbe3ee;
  border-radius: 0.75rem;
  padding: 1rem;
  margin-bottom: 1rem;
}

.bea-stock-panel--wide {
  grid-column: 1 / -1;
}

.bea-stock-panel h2,
.bea-stock-panel summary {
  margin: 0 0 0.75rem;
  font-size: 1rem;
}

.bea-stock-panel__empty {
  color: #64748b;
  margin: 0;
}

.bea-stock-bars__row {
  display: grid;
  grid-template-columns: 8rem 1fr 3rem;
  gap: 0.5rem;
  align-items: center;
  margin-bottom: 0.45rem;
  font-size: 0.82rem;
}

.bea-stock-bars__track {
  height: 0.55rem;
  background: #e2e8f0;
  border-radius: 999px;
  overflow: hidden;
}

.bea-stock-bars__fill {
  height: 100%;
  background: #2874a6;
  border-radius: 999px;
}

.bea-stock-bars__fill--alt {
  background: #0e9f6e;
}

.bea-stock-month {
  display: flex;
  align-items: flex-end;
  gap: 0.65rem;
  min-height: 8rem;
}

.bea-stock-month__col {
  flex: 1;
  text-align: center;
  font-size: 0.7rem;
}

.bea-stock-month__bar {
  background: #1a5278;
  border-radius: 0.35rem 0.35rem 0 0;
  min-height: 0.25rem;
  margin: 0 auto 0.35rem;
  width: 70%;
}

.bea-stock-toolbar,
.bea-stock-form {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
  align-items: end;
  margin-bottom: 1rem;
}

.bea-stock-form__grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
  gap: 0.75rem;
  width: 100%;
  margin-bottom: 0.85rem;
}

.bea-stock-toolbar input,
.bea-stock-toolbar select,
.bea-stock-form input,
.bea-stock-form select,
.bea-stock-fiche input,
.bea-stock-fiche select {
  font: inherit;
  padding: 0.4rem 0.55rem;
  border: 1px solid #cbd5e1;
  border-radius: 0.4rem;
  min-width: 9rem;
}

.bea-stock-form label,
.bea-stock-toolbar label,
.bea-stock-fiche__meta label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-size: 0.8rem;
  color: #475569;
}

.bea-stock-check {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  font-size: 0.85rem;
}

.bea-stock-table-scroll {
  overflow: auto;
  max-height: min(42rem, calc(100vh - 20rem));
}
.bea-stock-table-scroll .bea-stock-table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  background: #f8fafc;
  box-shadow: 0 1px 0 #e2e8f0;
}
.bea-stock-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}

.bea-stock-table th,
.bea-stock-table td {
  border-bottom: 1px solid #e2e8f0;
  padding: 0.55rem 0.4rem;
  text-align: left;
}

.bea-stock-pill,
.bea-stock-badge {
  display: inline-block;
  padding: 0.15rem 0.45rem;
  border-radius: 999px;
  background: #e2e8f0;
  font-size: 0.72rem;
  text-transform: uppercase;
}

.bea-stock-pill[data-niveau='faible'],
.bea-stock-badge[data-niveau='faible'] {
  background: #fef3c7;
  color: #92400e;
}

.bea-stock-pill[data-niveau='epuise'],
.bea-stock-badge[data-niveau='epuise'] {
  background: #fee2e2;
  color: #991b1b;
}

.bea-stock-pill[data-niveau='normal'],
.bea-stock-badge[data-niveau='normal'] {
  background: #dcfce7;
  color: #166534;
}

.bea-stock-fiche {
  background: #fff;
  border: 1px solid #dbe3ee;
  border-radius: 0.85rem;
  padding: 1.25rem;
}

.bea-stock-fiche__banner {
  display: flex;
  gap: 0.85rem;
  align-items: center;
  padding: 0.85rem 1rem;
  margin: -1.25rem -1.25rem 1rem;
  border-radius: 0.85rem 0.85rem 0 0;
  background: linear-gradient(90deg, #1a5278, #0f172a);
  color: #fff;
}

.bea-stock-fiche__banner span {
  display: block;
  font-size: 0.8rem;
  opacity: 0.85;
}

.bea-stock-fiche__meta {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(12rem, 1fr));
  gap: 0.75rem;
  margin-bottom: 1rem;
}

.bea-stock-fiche__visas {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  margin: 1.25rem 0;
  min-height: 4rem;
  font-size: 0.85rem;
  color: #475569;
}

.bea-stock-fiche__visas > div {
  border: 1px dashed #cbd5e1;
  border-radius: 0.5rem;
  padding: 0.75rem;
}

.bea-stock-fiche__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}

@media (max-width: 900px) {
  .bea-stock {
    grid-template-columns: 1fr;
  }

  .bea-stock__side {
    position: sticky;
    top: 0;
    z-index: 5;
  }

  .bea-stock__nav {
    flex-direction: row;
    flex-wrap: wrap;
  }

  .bea-stock-charts {
    grid-template-columns: 1fr;
  }
}

/* ——— Stock MG — chrome listes / modals / CRUD (partagé) ——— */
.bea-mg {
  max-width: 74rem;
  animation: beaMgIn 0.4s ease both;
}
.bea-mg__head {
  display: flex;
  flex-wrap: wrap;
  gap: 1rem;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 1.15rem;
}
.bea-mg__head h1 {
  margin: 0.15rem 0 0;
  font-size: clamp(1.35rem, 2.2vw, 1.65rem);
  letter-spacing: -0.02em;
  color: #0f172a;
}
.bea-mg__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.bea-mg__btn {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  border: 1px solid transparent;
  border-radius: 0.55rem;
  padding: 0.5rem 0.9rem;
  font: inherit;
  font-size: 0.88rem;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease, background 0.15s ease;
  text-decoration: none;
  color: inherit;
  background: #fff;
}
.bea-mg__btn mat-icon {
  font-size: 1.1rem;
  width: 1.1rem;
  height: 1.1rem;
}
.bea-mg__btn--primary {
  background: #1a5278;
  color: #fff;
  box-shadow: 0 4px 12px rgba(26, 82, 120, 0.25);
}
.bea-mg__btn--primary:hover {
  background: #154360;
  transform: translateY(-1px);
}
.bea-mg__btn--ghost {
  border-color: #cbd5e1;
  color: #1a5278;
}
.bea-mg__btn--ghost:hover {
  border-color: #1a5278;
  background: #f8fafc;
}
.bea-mg__btn--danger {
  background: #b91c1c;
  color: #fff;
}
.bea-mg__btn:disabled {
  opacity: 0.55;
  cursor: not-allowed;
  transform: none;
}

.bea-mg__search {
  display: flex;
  flex-wrap: wrap;
  gap: 0.65rem;
  align-items: stretch;
  margin-bottom: 1.15rem;
  padding: 0.85rem;
  background: #fff;
  border: 1px solid #dbe3ee;
  border-radius: 0.95rem;
  box-shadow: 0 6px 18px rgba(15, 23, 42, 0.04);
}
.bea-mg__field {
  display: flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.35rem 0.7rem;
  background: #f8fafc;
  border: 1px solid #e2e8f0;
  border-radius: 0.6rem;
  min-width: 10rem;
}
.bea-mg__field--grow {
  flex: 1 1 14rem;
}
.bea-mg__field:focus-within {
  border-color: #1a5278;
  box-shadow: 0 0 0 3px rgba(26, 82, 120, 0.12);
  background: #fff;
}
.bea-mg__field mat-icon {
  color: #64748b;
  font-size: 1.15rem;
  width: 1.15rem;
  height: 1.15rem;
}
.bea-mg__field input,
.bea-mg__field select {
  flex: 1;
  border: 0;
  background: transparent;
  font: inherit;
  font-size: 0.9rem;
  outline: none;
  min-width: 0;
  padding: 0.35rem 0;
}

.bea-mg__panel {
  background: #fff;
  border: 1px solid #dbe3ee;
  border-radius: 1rem;
  overflow: hidden;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
  margin-bottom: 1rem;
}
.bea-mg__panel-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.95rem 1.15rem;
  border-bottom: 1px solid #eef2f7;
  background: linear-gradient(180deg, #f8fafc, #fff);
}
.bea-mg__panel-top h2 {
  margin: 0;
  font-size: 1rem;
  color: #0f172a;
}
.bea-mg__count {
  font-size: 0.78rem;
  color: #64748b;
  background: #eef2f7;
  padding: 0.25rem 0.6rem;
  border-radius: 999px;
}

.bea-stock-period-banner {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 0.75rem;
  margin: 0.85rem 1.15rem 0.65rem;
  padding: 0.7rem 1rem;
  background: #f8fafc;
  border: 1px solid #dbe3ee;
  border-radius: 0.75rem;
}
.bea-stock-period-banner[data-statut='CLOTUREE'] {
  background: #f8fafc;
  border-color: #94a3b8;
}
.bea-stock-period-banner__copy {
  display: flex;
  flex-direction: column;
  gap: 0.12rem;
  min-width: 0;
}
.bea-stock-period-banner__label {
  font-size: 0.7rem;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: #64748b;
  font-weight: 600;
}
.bea-stock-period-banner strong {
  font-size: 1.02rem;
  color: #0f172a;
}
.bea-stock-period-alert {
  display: flex;
  align-items: center;
  gap: 0.45rem;
  margin: 0 1.15rem 0.85rem;
  padding: 0.6rem 0.9rem;
  border-radius: 0.75rem;
  background: #fffbeb;
  border: 1px solid #f59e0b;
  color: #92400e;
  text-decoration: none;
  font-weight: 600;
  font-size: 0.86rem;
}
.bea-stock-period-alert mat-icon {
  font-size: 1.15rem;
  width: 1.15rem;
  height: 1.15rem;
  flex-shrink: 0;
}
.bea-stock-period-alert:hover {
  background: #fef3c7;
}
.bea-mg__table-scroll {
  max-height: min(42rem, calc(100vh - 20rem));
  overflow: auto;
  border-top: 1px solid #eef2f7;
}
.bea-mg__table-scroll .bea-mg__table thead th,
.bea-mg__table-scroll .bea-ach__table thead th,
.bea-mg__table-scroll .bea-stock-table thead th,
.bea-mg__table-scroll .bea-art__table thead th {
  position: sticky;
  top: 0;
  z-index: 1;
  box-shadow: 0 1px 0 #e2e8f0;
}

.bea-mg__table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}
.bea-mg__table th {
  text-align: left;
  padding: 0.7rem 1rem;
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #64748b;
  background: #f8fafc;
  border-bottom: 1px solid #e2e8f0;
  white-space: nowrap;
}
.bea-mg__table td {
  padding: 0.75rem 1rem;
  border-bottom: 1px solid #cbd5e1;
  color: #0f172a;
  vertical-align: middle;
}
.bea-mg__table input,
.bea-mg__table select,
.bea-mg__table textarea,
.bea-ach__table input,
.bea-ach__table select,
.bea-ach__table textarea {
  font: inherit;
  font-weight: 500;
  font-size: 0.9rem;
  width: 100%;
  min-width: 0;
  box-sizing: border-box;
  padding: 0.48rem 0.7rem;
  border: 1.5px solid #475569;
  border-radius: 0.4rem;
  background: #fff;
  color: #0f172a;
}
.bea-mg__table input[type='number'],
.bea-ach__table input[type='number'] {
  width: 8.5rem;
  max-width: 100%;
  text-align: right;
}
.bea-mg__table input:focus,
.bea-mg__table select:focus,
.bea-mg__table textarea:focus,
.bea-ach__table input:focus,
.bea-ach__table select:focus,
.bea-ach__table textarea:focus {
  outline: none;
  border-color: #1a5278;
  box-shadow: 0 0 0 3px rgba(26, 82, 120, 0.16);
}
.bea-mg__lignes {
  margin-top: 1rem;
  border: 1.5px solid #475569;
  border-radius: 0.7rem;
  overflow: hidden;
  background: #fff;
}
.bea-mg__lignes .bea-mg__table-scroll {
  margin-top: 0;
  border-top: 0;
  max-height: none;
}
.bea-mg__table tbody tr {
  transition: background 0.15s ease;
  animation: beaMgRise 0.4s ease both;
}
.bea-mg__table tbody tr:hover {
  background: #f8fafc;
}
.bea-mg__code {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.82rem;
  background: #eef2f7;
  padding: 0.15rem 0.4rem;
  border-radius: 0.3rem;
  color: #1a5278;
}
.bea-mg__th-actions,
.bea-mg__actions-cell {
  text-align: right;
  white-space: nowrap;
}
.bea-mg__icon-btn {
  display: inline-grid;
  place-items: center;
  width: 2rem;
  height: 2rem;
  margin-left: 0.15rem;
  border: 1px solid #e2e8f0;
  border-radius: 0.45rem;
  background: #fff;
  color: #475569;
  cursor: pointer;
  transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease, transform 0.15s ease;
}
.bea-mg__icon-btn mat-icon {
  font-size: 1.05rem;
  width: 1.05rem;
  height: 1.05rem;
}
.bea-mg__icon-btn:hover {
  color: #1a5278;
  border-color: #94a3b8;
  transform: translateY(-1px);
}
.bea-mg__icon-btn:disabled {
  opacity: 0.45;
  cursor: not-allowed;
  transform: none;
}
.bea-mg__icon-btn--danger:hover {
  color: #b91c1c;
  border-color: #fca5a5;
  background: #fef2f2;
}
.bea-mg__icon-btn--warn:hover {
  color: #b45309;
  border-color: #fcd34d;
  background: #fffbeb;
}

.bea-mg__backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.45);
  backdrop-filter: blur(2px);
  z-index: 40;
  animation: beaMgFade 0.2s ease both;
}
.bea-mg__modal {
  position: fixed;
  z-index: 41;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: min(36rem, calc(100vw - 1.5rem));
  max-height: calc(100vh - 2rem);
  overflow: auto;
  background: #fff;
  border-radius: 1rem;
  box-shadow: 0 24px 48px rgba(15, 23, 42, 0.28);
  animation: beaMgModal 0.28s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.bea-mg__modal--sm {
  width: min(26rem, calc(100vw - 1.5rem));
}
.bea-mg__modal--lg {
  width: min(48rem, calc(100vw - 1.5rem));
}
.bea-mg__modal-head {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  gap: 1rem;
  padding: 1.1rem 1.25rem 0.85rem;
  border-bottom: 1px solid #eef2f7;
}
.bea-mg__modal-head h2 {
  margin: 0.1rem 0 0;
  font-size: 1.15rem;
  color: #0f172a;
}
.bea-mg__modal-body {
  padding: 1rem 1.25rem;
}
.bea-mg__modal-foot {
  display: flex;
  justify-content: flex-end;
  gap: 0.5rem;
  padding: 0 1.25rem 1.15rem;
}
.bea-mg__grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 0.75rem;
}
.bea-mg__grid--1 {
  grid-template-columns: 1fr;
}
.bea-mg__span2 {
  grid-column: 1 / -1;
}
.bea-mg__grid label {
  display: flex;
  flex-direction: column;
  gap: 0.3rem;
  font-size: 0.78rem;
  color: #475569;
  font-weight: 600;
}
.bea-mg__grid input,
.bea-mg__grid select,
.bea-mg__grid textarea {
  font: inherit;
  font-weight: 500;
  font-size: 0.9rem;
  padding: 0.55rem 0.7rem;
  border: 1.5px solid #475569;
  border-radius: 0.45rem;
  background: #fff;
  color: #0f172a;
}
.bea-mg__grid input:focus,
.bea-mg__grid select:focus,
.bea-mg__grid textarea:focus {
  outline: none;
  border-color: #1a5278;
  box-shadow: 0 0 0 3px rgba(26, 82, 120, 0.12);
}
.bea-mg__empty {
  text-align: center;
  padding: 2.25rem 1rem;
  color: #64748b;
}
.bea-mg__empty mat-icon {
  font-size: 2rem;
  width: 2rem;
  height: 2rem;
  opacity: 0.4;
}
.bea-mg__cards {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
}
@media (max-width: 900px) {
  .bea-mg__cards {
    grid-template-columns: 1fr;
  }
  .bea-mg__grid {
    grid-template-columns: 1fr;
  }
  .bea-mg__span2 {
    grid-column: auto;
  }
}
@keyframes beaMgIn {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes beaMgRise {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
@keyframes beaMgFade {
  from {
    opacity: 0;
  }
  to {
    opacity: 1;
  }
}
@keyframes beaMgModal {
  from {
    opacity: 0;
    transform: translate(-50%, -46%) scale(0.96);
  }
  to {
    opacity: 1;
    transform: translate(-50%, -50%) scale(1);
  }
}
@media (prefers-reduced-motion: reduce) {
  .bea-mg,
  .bea-mg__table tbody tr,
  .bea-mg__backdrop,
  .bea-mg__modal {
    animation: none !important;
  }
}

/* ——— Notes de frais — design & animations ——— */
.bea-nf__registre-scroll {
  max-height: min(22rem, calc(100vh - 20rem));
  overflow: auto;
}
.bea-nf .bea-mg__head h1 {
  background: linear-gradient(120deg, #0f172a 0%, #1a5278 55%, #2874a6 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.bea-nf-kpi {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 0.85rem;
  margin-bottom: 1rem;
}
.bea-nf-kpi__card {
  position: relative;
  overflow: hidden;
  padding: 1.1rem 1.15rem;
  background: #fff;
  border: 1px solid #dbe3ee;
  border-radius: 1rem;
  box-shadow: 0 8px 22px rgba(15, 23, 42, 0.05);
  animation: beaMgRise 0.45s ease both;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.bea-nf-kpi__card:nth-child(1) { animation-delay: 0.05s; }
.bea-nf-kpi__card:nth-child(2) { animation-delay: 0.1s; }
.bea-nf-kpi__card:nth-child(3) { animation-delay: 0.15s; }
.bea-nf-kpi__card:nth-child(4) { animation-delay: 0.2s; }
.bea-nf-kpi__card::before {
  content: '';
  position: absolute;
  inset: 0 auto 0 0;
  width: 4px;
  background: linear-gradient(180deg, #1a5278, #3498db);
}
.bea-nf-kpi__card:hover {
  transform: translateY(-3px);
  border-color: #94a3b8;
  box-shadow: 0 14px 28px rgba(26, 82, 120, 0.12);
}
.bea-nf-kpi__card p {
  margin: 0;
  font-size: 0.7rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #64748b;
  font-weight: 700;
}
.bea-nf-kpi__card strong {
  display: block;
  margin-top: 0.35rem;
  font-size: clamp(1.25rem, 2vw, 1.7rem);
  letter-spacing: -0.03em;
  color: #0f172a;
}
.bea-nf-split {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(8.5rem, 1fr));
  gap: 0.65rem;
}
.bea-nf-split__item {
  padding: 0.85rem 0.75rem;
  border-radius: 0.75rem;
  background: linear-gradient(180deg, #f8fafc, #fff);
  border: 1px solid #e2e8f0;
  text-align: center;
  animation: beaMgRise 0.4s ease both;
  transition: border-color 0.15s ease, transform 0.15s ease;
}
.bea-nf-split__item:hover {
  border-color: #1a5278;
  transform: translateY(-2px);
}
.bea-nf-split__item strong {
  display: block;
  font-size: 1.35rem;
  color: #1a5278;
}
.bea-nf-split__item span {
  font-size: 0.72rem;
  color: #64748b;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.bea-nf-fiche {
  border: 2px solid #0f172a;
  border-radius: 0.35rem;
  overflow: hidden;
  background: #fff;
  animation: beaNfFicheIn 0.5s cubic-bezier(0.22, 1, 0.36, 1) both;
  box-shadow: 0 12px 32px rgba(15, 23, 42, 0.08);
}
.bea-nf-fiche__top {
  display: grid;
  grid-template-columns: 0.9fr 1.3fr 1.4fr;
  border-bottom: 2px solid #0f172a;
}
.bea-nf-fiche__brand,
.bea-nf-fiche__dept,
.bea-nf-fiche__id {
  padding: 0.75rem 0.85rem;
  border-right: 1.5px solid #0f172a;
}
.bea-nf-fiche__id { border-right: 0; padding: 0; }
.bea-nf-fiche__brand {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.35rem;
  text-align: center;
}
.bea-nf-fiche__brand img { width: 52px; height: 52px; object-fit: contain; }
.bea-nf-fiche__brand strong { font-size: 0.82rem; color: #1a5278; }
.bea-nf-fiche__dept {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  text-align: center;
  gap: 0.25rem;
  font-size: 0.82rem;
  font-weight: 700;
  color: #0f172a;
  line-height: 1.35;
}
.bea-nf-fiche__dept span { font-weight: 600; color: #334155; }
.bea-nf-fiche__id-row {
  display: grid;
  grid-template-columns: 9.5rem 1fr;
  border-bottom: 1px solid #0f172a;
  min-height: 2.1rem;
}
.bea-nf-fiche__id-row:last-child { border-bottom: 0; }
.bea-nf-fiche__id-row label {
  display: flex;
  align-items: center;
  padding: 0.35rem 0.55rem;
  background: #eef2f7;
  border-right: 1px solid #0f172a;
  font-size: 0.72rem;
  font-weight: 700;
  color: #334155;
  margin: 0;
}
.bea-nf-fiche__id-row input,
.bea-nf-fiche__id-row select {
  border: 0 !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  background: #fff !important;
  height: 100%;
  padding: 0.35rem 0.55rem;
  font-weight: 600;
}
.bea-nf-fiche__title {
  margin: 0;
  padding: 0.55rem 0.75rem;
  text-align: center;
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0.02em;
  border-bottom: 1.5px solid #0f172a;
  background: #f8fafc;
  color: #0f172a;
}
.bea-nf-fiche__title-row {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 0.5rem;
  padding: 0.65rem 0.85rem;
  border-bottom: 1.5px solid #0f172a;
  background: #f8fafc;
  font-weight: 800;
  color: #0f172a;
}
.bea-nf-fiche__title-row select,
.bea-nf-fiche__title-row input {
  border: 1.5px solid #475569 !important;
  border-radius: 0.4rem !important;
  padding: 0.4rem 0.55rem !important;
  font: inherit;
  font-weight: 700 !important;
  min-width: 12rem;
  background: #fff !important;
}
.bea-nf-fiche__mode {
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
  min-width: 9.5rem;
}
.bea-nf-fiche__mode input {
  border: 1.5px solid #475569 !important;
  border-radius: 0.35rem !important;
  padding: 0.35rem 0.45rem !important;
  font: inherit;
  background: #fff !important;
}
.bea-nf-fiche .bea-mg__table th {
  background: #e8eef5;
  color: #0f172a;
  border-bottom-color: #0f172a;
  text-transform: none;
  letter-spacing: 0;
  font-size: 0.78rem;
}
.bea-nf-fiche .bea-mg__table td {
  border-bottom-color: #94a3b8;
}
.bea-nf-fiche__total {
  display: flex;
  justify-content: flex-end;
  gap: 1.5rem;
  padding: 0.65rem 1rem;
  border-top: 2px solid #0f172a;
  font-weight: 800;
  background: #f8fafc;
}
.bea-nf-fiche__signs {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1rem;
  padding: 1.25rem 1rem 1.5rem;
  text-align: center;
  font-size: 0.85rem;
  font-weight: 700;
  color: #1a5278;
}
.bea-nf-fiche__signs em {
  display: none;
}
.bea-nf-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.85rem 1.35rem;
  padding: 0.85rem 1rem 1.15rem;
  border-top: 1px solid #e2e8f0;
  background: #f8fafc;
}
.bea-nf-actions__group {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.45rem;
}
.bea-nf-actions__label {
  display: block;
  width: 100%;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #64748b;
  margin-bottom: 0.1rem;
}
@keyframes beaNfFicheIn {
  from { opacity: 0; transform: translateY(12px) scale(0.985); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes beaNfPulse {
  0%, 100% { box-shadow: 0 0 0 0 rgba(26, 82, 120, 0.15); }
  50% { box-shadow: 0 0 0 8px rgba(26, 82, 120, 0); }
}
.bea-nf-alert-row {
  animation: beaMgRise 0.35s ease both;
}
@media (max-width: 900px) {
  .bea-nf-kpi { grid-template-columns: 1fr 1fr; }
  .bea-nf-fiche__top { grid-template-columns: 1fr; }
  .bea-nf-fiche__brand,
  .bea-nf-fiche__dept { border-right: 0; border-bottom: 1.5px solid #0f172a; }
}
@media (prefers-reduced-motion: reduce) {
  .bea-nf-kpi__card,
  .bea-nf-split__item,
  .bea-nf-fiche,
  .bea-nf-alert-row {
    animation: none !important;
  }
}
